from __future__ import annotations

import base64
import gzip
from pathlib import Path

PAYLOAD = """"""

root = Path(".")
runtime_v75 = root / "neptune-video-engine/runtime_v75.py"
runtime_v75.write_bytes(gzip.decompress(base64.b64decode(PAYLOAD)))

runtime = root / "neptune-video-engine/runtime.py"
text = runtime.read_text(encoding="utf-8")
old = "from runtime_v74 import app as app  # noqa: E402,F401"
new = "from runtime_v75 import app as app  # noqa: E402,F401"
if old not in text:
    raise SystemExit("runtime entrypoint anchor missing")
runtime.write_text(text.replace(old, new, 1), encoding="utf-8")

dockerfile = root / "neptune-video-engine/Dockerfile"
text = dockerfile.read_text(encoding="utf-8")
old = "COPY app.py runtime.py runtime_v74.py ./"
new = """COPY app.py runtime.py runtime_v74.py runtime_v75.py ./

RUN curl -fL --retry 3 --retry-delay 2 \\
  https://github.com/opencv/opencv_zoo/raw/main/models/face_detection_yunet/face_detection_yunet_2023mar.onnx \\
  -o /app/face_detection_yunet_2023mar.onnx"""
if old not in text:
    raise SystemExit("Dockerfile COPY anchor missing")
dockerfile.write_text(text.replace(old, new, 1), encoding="utf-8")

installer = root / "neptune-tv-media-cloudflare/public/studio/install-neptune-video-engine.ps1"
text = installer.read_text(encoding="utf-8")
text = text.replace(
    'Read-Host "Clé OpenAI locale (facultatif, Entrée pour utiliser Ollama/règles Neptune)"',
    'Read-Host "Clé OpenAI locale pour les hooks avancés (recommandée ; Entrée = sélection locale v75)"',
)
text = text.replace("NEPTUNE_MIN_EDITORIAL_SCORE=65", "NEPTUNE_MIN_EDITORIAL_SCORE=60")
installer.write_text(text, encoding="utf-8")

bridge = root / "neptune-tv-media-cloudflare/public/studio/video-ai-engine-v73.js"
text = bridge.read_text(encoding="utf-8")
text = text.replace(
    "const REQUIRED_ENGINE_VERSION = 'neptune-video-engine-20260803-v74';",
    "const REQUIRED_ENGINE_VERSION = 'neptune-video-engine-20260803-v75';",
)
text = text.replace("Moteur Neptune v74 connecté", "Moteur Neptune v75 connecté")
text = text.replace("Installez la v74", "Installez la v75")
text = text.replace(
    "intervenant suivi, silences resserrés, sous-titres verticaux et sélection OpenAI multipasse",
    "sélection par phrases, cadrage YuNet sécurisé, sous-titres mot à mot et hooks exacts",
)
bridge.write_text(text, encoding="utf-8")

html = root / "neptune-tv-media-cloudflare/public/studio/video-ai.html"
text = html.read_text(encoding="utf-8").replace(
    "/studio/video-ai-engine-v73.js?v=74",
    "/studio/video-ai-engine-v73.js?v=75",
)
html.write_text(text, encoding="utf-8")

entry = root / "neptune-tv-media-cloudflare/src/entry-v16.js"
text = entry.read_text(encoding="utf-8")
text = text.replace(
    "const RELEASE = 'neptune-video-engine-20260802-v73';",
    "const RELEASE = 'neptune-video-engine-20260803-v75';",
)
text = text.replace(
    "const PERMANENT_ENGINE_UI_JS = '/studio/video-ai-engine-v73.js?v=74';",
    "const PERMANENT_ENGINE_UI_JS = '/studio/video-ai-engine-v73.js?v=75';",
)
text = text.replace(
    "persistent-local-service-faster-whisper-openai-ollama-opencv-ffmpeg-studio-sync-browser-fallback",
    "persistent-local-service-faster-whisper-sentence-density-openai-yunet-ffmpeg-studio-sync-browser-fallback",
)
text = text.replace(
    "local-ffmpeg-opencv-smart-crop-vertical-1080x1920-ass-subtitles",
    "local-ffmpeg-yunet-safe-layout-vertical-1080x1920-word-focus-ass-subtitles",
)
entry.write_text(text, encoding="utf-8")

smoke = root / "neptune-tv-media-cloudflare/scripts/smoke-test-v73.mjs"
text = smoke.read_text(encoding="utf-8")
text = text.replace("/studio/video-ai-engine-v73.js?v=74", "/studio/video-ai-engine-v73.js?v=75")
text = text.replace("neptune-video-engine-20260803-v74", "neptune-video-engine-20260803-v75")
text = text.replace("Neptune Video Engine v74 validé", "Neptune Video Engine v75 validé")
smoke.write_text(text, encoding="utf-8")

print("Applied Neptune Video Engine v75 runtime and Studio version contract.")
